texts = {}
for f, _, _, _ in ROWS:
    texts.setdefault(f, (draft / f).read_text())
bad = []
# Each count is checked in memory against the text as it stands when its row applies (earlier
# rows on the same file already replaced). Nothing is written until every row has passed.
# The rows also cover the stale-term sweep (B1, Authenticated Origin Pulls, $7 alert,
# Microsoft.OpenTelemetry, app registration). Remaining hits in docs/design.md are intentional:
# rejected-alternative mentions in D-01, D-03, D-12 and D-25.
work = dict(texts)
for f, o, n, want in ROWS:
    got = work[f].count(o)
    if got != want:
        bad.append((f, o[:60], got, want))
        continue
    work[f] = work[f].replace(o, n)
if bad:
    for b in bad:
        print("ABORT", *b)
    sys.exit(1)
for f, o, n, want in ROWS:
    print(f"OK {f} x{want}")
for f, t in work.items():
    (draft / f).write_text(t)
print(f"wrote {len(work)} files, {len(ROWS)} rows")
